create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,first_name text not null default '',last_name text not null default '',created_at timestamptz not null default now());
create table if not exists expense_categories(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,parent_id uuid references expense_categories(id) on delete set null,hidden boolean not null default false,created_at timestamptz not null default now());
create table if not exists expenses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,amount numeric(14,2) not null check(amount>=0),description text not null,date date not null,category_id uuid references expense_categories(id) on delete set null,deleted_at timestamptz,created_at timestamptz not null default now());
create table if not exists income(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,amount numeric(14,2) not null check(amount>=0),description text not null,date date not null,category text,created_at timestamptz not null default now());
create table if not exists assets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null,name text not null,amount numeric(14,2) not null default 0,created_at timestamptz not null default now());
create table if not exists liabilities(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null,name text not null,amount numeric(14,2) not null default 0,created_at timestamptz not null default now());
create table if not exists budgets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,category_id uuid references expense_categories(id) on delete cascade,month date not null,amount numeric(14,2) not null,created_at timestamptz not null default now());
create table if not exists goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,target_amount numeric(14,2) not null,current_amount numeric(14,2) not null default 0,monthly_amount numeric(14,2) not null default 0,created_at timestamptz not null default now());
create table if not exists tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,due_date date,priority text not null default 'normal',status text not null default 'open',note text,created_at timestamptz not null default now());
create table if not exists notes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,content text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists user_preferences(id uuid primary key references auth.users(id) on delete cascade,theme text not null default 'light',text_size text not null default 'normal',assistant_enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null,title text not null,body text not null default '',read boolean not null default false,created_at timestamptz not null default now());
alter table profiles enable row level security;alter table expense_categories enable row level security;alter table expenses enable row level security;alter table income enable row level security;alter table assets enable row level security;alter table liabilities enable row level security;alter table budgets enable row level security;alter table goals enable row level security;alter table tasks enable row level security;alter table notes enable row level security;alter table user_preferences enable row level security;alter table notifications enable row level security;
create policy profile_isolation on profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy categories_isolation on expense_categories for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy expenses_isolation on expenses for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy income_isolation on income for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy assets_isolation on assets for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy liabilities_isolation on liabilities for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy budgets_isolation on budgets for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy goals_isolation on goals for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy tasks_isolation on tasks for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy notes_isolation on notes for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy prefs_isolation on user_preferences for all using(id=auth.uid()) with check(id=auth.uid());
create policy notifications_isolation on notifications for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,first_name,last_name) values(new.id,coalesce(new.raw_user_meta_data->>'first_name',''),coalesce(new.raw_user_meta_data->>'last_name','')) on conflict(id) do nothing;insert into public.user_preferences(id) values(new.id) on conflict(id) do nothing;return new;end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();